questions.answer:
function checkPasswords() {
  if (confirm.value !== password.value) {
    confirm.setCustomValidity("Passwords do not match");
  } else {
    confirm.setCustomValidity("");
  }
}

password.addEventListener("input", checkPasswords);
confirm.addEventListener("input", checkPasswords);

form.addEventListener("submit", (event) => {
  checkPasswords();
  if (!form.checkValidity()) {
    event.preventDefault();
    form.reportValidity();
  }
});

setCustomValidity sets validity.customError and the message shown by reportValidity. Clearing with an empty string is mandatory: otherwise the field stays invalid forever, even after the values match. Listening on both fields catches edits in either order, including pasting. Re-checking on submit closes the race where the user edits and submits before the input event runs. The check is UX only; the server must compare hashes again.

